// GameAI 前端入口
// Backend binding will be generated by Wails

import './style.css'

const quickInputOverlay = document.getElementById('quick-input-overlay')
const quickInputTextarea = document.getElementById('quick-input-textarea')
const conversationContainer = document.getElementById('conversation')

// 缓存早期日志，等 DOM 加载后再显示
let logContainer = null
let earlyLogs = []

// 监听来自Go后端的快速输入显示事件 (Wails v2 uses CustomEvent directly)
window.addEventListener('showQuickInput', (event) => {
  showQuickInput()
})

// 显示快速输入框
function showQuickInput() {
  quickInputOverlay.classList.remove('hidden')
  quickInputTextarea.value = ''
  quickInputTextarea.focus()
}

// 隐藏快速输入框
function hideQuickInput() {
  quickInputOverlay.classList.add('hidden')
  quickInputTextarea.value = ''
}

// 添加消息到对话
function addMessage(role, content) {
  const messageDiv = document.createElement('div')
  messageDiv.className = `message ${role}`

  const headerDiv = document.createElement('div')
  headerDiv.className = 'message-header'
  headerDiv.textContent = role === 'user' ? '你' : 'AI'

  const contentDiv = document.createElement('div')
  contentDiv.className = 'message-content'
  contentDiv.textContent = content

  messageDiv.appendChild(headerDiv)
  messageDiv.appendChild(contentDiv)
  conversationContainer.appendChild(messageDiv)

  // 滚动到底部
  conversationContainer.scrollTop = conversationContainer.scrollHeight

  return contentDiv
}

// 追加内容到最后一条助手消息（流式响应）
function appendToLastAssistantMessage(content) {
  const messages = conversationContainer.querySelectorAll('.message.assistant')
  let contentDiv

  if (messages.length === 0) {
    // 没有助手消息，创建新的
    const messageDiv = document.createElement('div')
    messageDiv.className = 'message assistant'

    const headerDiv = document.createElement('div')
    headerDiv.className = 'message-header'
    headerDiv.textContent = 'AI'

    contentDiv = document.createElement('div')
    contentDiv.className = 'message-content'
    contentDiv.textContent = ''

    messageDiv.appendChild(headerDiv)
    messageDiv.appendChild(contentDiv)
    conversationContainer.appendChild(messageDiv)
  } else {
    const lastMessage = messages[messages.length - 1]
    contentDiv = lastMessage.querySelector('.message-content')
  }

  contentDiv.textContent += content
  conversationContainer.scrollTop = conversationContainer.scrollHeight
}

// 处理快速输入提交
async function handleSubmit(text) {
  if (!text) return

  // 添加用户消息
  addMessage('user', text)

  // 检查 Agent 是否配置
  const status = await window.AgentBindings.GetConfigStatus()
  if (!status.configured) {
    addMessage('assistant', 'LLM 未配置，请配置 API Key 后重试。')
    return
  }

  try {
    // 创建空的助手消息用于流式填充
    addMessage('assistant', '')
    // 开始流式响应
    await window.AgentBindings.ChatStream(text)
  } catch (err) {
    addMessage('assistant', `错误: ${err.message || String(err)}`)
  }
}

// 处理键盘事件
quickInputTextarea.addEventListener('keydown', async (e) => {
  // Esc 关闭窗口
  if (e.key === 'Escape') {
    e.preventDefault()
    await window.InputBindings.CancelQuickInput()
    hideQuickInput()
    return
  }

  // Enter 提交（如果没有按住 Shift）
  if (e.key === 'Enter' && !e.shiftKey) {
    e.preventDefault()
    const text = quickInputTextarea.value.trim()
    if (text) {
      await handleSubmit(text)
      await window.InputBindings.SubmitQuickInput(text)
      hideQuickInput()
    } else {
      await window.InputBindings.CancelQuickInput()
      hideQuickInput()
    }
    return
  }
})

// 点击遮罩层关闭
quickInputOverlay.addEventListener('click', (e) => {
  if (e.target === quickInputOverlay) {
    hideQuickInput()
  }
})

// 流式响应事件：接收 chunk
window.addEventListener('llmChunk', (event) => {
  if (event.detail && event.detail.content) {
    appendToLastAssistantMessage(event.detail.content)
  }
})

// 注册Go后端回调：显示快速输入
window.showQuickInput = showQuickInput

document.addEventListener('DOMContentLoaded', () => {
  console.log('GameAI initialized')
  // 获取日志容器并显示缓存的早期日志
  logContainer = document.getElementById('log-container')
  // 播放缓存的早期日志
  if (earlyLogs.length > 0) {
    earlyLogs.forEach(({ level, message }) => addLogEntry(level, message))
    earlyLogs = []
  }
})

// 添加一个测试按钮到页面方便测试截图
document.addEventListener('DOMContentLoaded', () => {
  const testDiv = document.createElement('div')
  testDiv.style.marginTop = '20px'
  testDiv.innerHTML = `
    <button id="testScreenshotBtn" style="
      padding: 10px 20px;
      background: #007acc;
      color: white;
      border: none;
      border-radius: 4px;
      cursor: pointer;
    ">测试全屏截图</button>
    <div id="screenshotResult" style="margin-top: 10px;"></div>
  `
  document.querySelector('.app-content').appendChild(testDiv)

  document.getElementById('testScreenshotBtn').addEventListener('click', async function() {
    const btn = this
    btn.disabled = true
    btn.textContent = '截图中...'

    try {
      const result = await window.AgentBindings.CaptureFullScreenshot()
      console.log('截图结果:', result)

      // 显示结果
      const container = document.getElementById('screenshotResult')
      container.innerHTML = `<p>✓ 截图成功: ${result.width} × ${result.height}, ${(result.data.length / 1024).toFixed(1)} KB</p>`

      // 显示图片
      const img = document.createElement('img')
      img.style.maxWidth = '100%'
      img.style.border = '2px solid #ccc'
      img.style.borderRadius = '4px'
      img.style.marginTop = '10px'

      // 将 Uint8Array 转 base64
      const binary = result.data.reduce((acc, byte) => acc + String.fromCharCode(byte), '')
      img.src = 'data:image/jpeg;base64,' + btoa(binary)
      container.appendChild(img)
    } catch (err) {
      console.error('截图失败:', err)
      const container = document.getElementById('screenshotResult')
      container.innerHTML = `<p style="color: red;">✗ 截图失败: ${err.message || String(err)}</p>`
    } finally {
      btn.disabled = false
      btn.textContent = '测试全屏截图'
    }
  })
})

// 添加日志到日志面板
function addLogEntry(level, message) {
  // 如果 DOM 还没准备好，缓存起来
  if (!logContainer) {
    earlyLogs.push({ level, message })
    return
  }

  const entryDiv = document.createElement('div')
  entryDiv.className = `log-entry ${level}`
  entryDiv.textContent = `[${new Date().toLocaleTimeString()}] [${level.toUpperCase()}] ${message}`
  logContainer.appendChild(entryDiv)

  // 滚动到底部
  logContainer.scrollTop = logContainer.scrollHeight

  // 限制最大行数，避免过多DOM
  const entries = logContainer.querySelectorAll('.log-entry')
  if (entries.length > 500) {
    logContainer.removeChild(entries[0])
  }
}

// 监听后端日志事件 (Wails v2 uses CustomEvent with detail)
window.addEventListener('log', (event) => {
  const detail = event.detail
  if (detail && detail.level && detail.message) {
    addLogEntry(detail.level, detail.message)
  }
})

// 也将浏览器console.log重定向到日志面板
const originalConsoleLog = console.log
const originalConsoleWarn = console.warn
const originalConsoleError = console.error

console.log = function(...args) {
  originalConsoleLog.apply(console, args)
  args.forEach(arg => {
    if (typeof arg === 'string') {
      addLogEntry('debug', arg)
    } else {
      addLogEntry('debug', JSON.stringify(arg))
    }
  })
}

console.warn = function(...args) {
  originalConsoleWarn.apply(console, args)
  args.forEach(arg => {
    if (typeof arg === 'string') {
      addLogEntry('warn', arg)
    } else {
      addLogEntry('warn', JSON.stringify(arg))
    }
  })
}

console.error = function(...args) {
  originalConsoleError.apply(console, args)
  args.forEach(arg => {
    if (typeof arg === 'string') {
      addLogEntry('error', arg)
    } else {
      addLogEntry('error', JSON.stringify(arg))
    }
  })
}
